available","coverId":15106508,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL59663551M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246008,"bound_title":"Fiela’s kind","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789088653049","evidence_url":"https://data.bibliotheken.nl/id/nbt/p363221387","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987346002}'::jsonb as exact union all select 'catalog_work_descriptions:39' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146026 and t.language='nl')='{"text":"Charlie en Eve kopen een oud huis dat zij willen opknappen. Op een dag staat er een gezin voor de deur waarvan de vader zegt er vroeger te hebben gewoond. Eve laat hen binnen om de kinderen rond te leiden. Vanaf dat moment doen zich gebeurtenissen voor die niet bij een gewoon bezoek passen. Het gezin lijkt bovendien niet te begrijpen dat het weer moet vertrekken. Terwijl de grenzen van haar eigen huis vervagen, wordt het voor Eve steeds moeilijker vast te stellen wat zij nog kan vertrouwen.","work_id":987146026,"evidence":[{"note":"Retain existing Work3407 We Used to Live Here / Marcus Kliewer and exact Dutch Vroeger woonden wij hier 9789021058658 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-025.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p450060934"],"refer