itionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p450060934"],"reference":"work:3407","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-025.json","sources":["https://openlibrary.org/works/OL37618590W","https://data.bibliotheken.nl/id/nbt/p450060934"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789021058658","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15165125,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL61181445M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246029,"bound_title":"Vroeger woonden wij hier","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789021058658","evidence_url":"https://data.bibliotheken.nl/id/nbt/p450060934","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987346012}'::jsonb as exact union all select 'catalog_work_descriptions:41' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146046 and t.language='nl')='{"text":"Na haar dood ontdekt Lily dat het hiernamaals anders is ingericht dan zij zich had voorgesteld. Tussen goden, andere wezens en uiteenlopende rijken kiest zij juist de hel als werkplek. Haar ervaring met klanten helpt haar om zielen naar hun bestemming te begeleiden. Een ontmoeting met demonengeneraal Bel groeit uit tot vriendschap en aantrekkingskracht. Terwijl Lily haar plaats probeert te vinden, ontstaat buiten hun vertrouwde grenzen een dreiging. Haar nieuwe begin vraagt daardoor meer dan alleen wennen aan een ongebruikelijke baan.","work_id":987146046,"evidence":[{"note":"Retain existing Work4994 For Whom the Belle Tolls / Jaysea Lynn and exact Dutch For Whom the Belle Tolls 9789020559521 Hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-025.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p450017036"],"reference":"work:4994","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-025.json","sources":["https://openlibrary.org/works/OL42457696W","https://data.bibliotheken.nl/id/nbt/p450017036"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789020559521","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15173576,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL61373726M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL42457696W","reviewed_at":"2026-11-03T09:26:38.922